def run(category, urgency, summary, draft, approved, problems):
    return {
        "triage": {
            "category": category,
            "urgency": urgency,
            "summary": summary,
            "reply": draft,
            "approved": approved,
            "problems": problems,
            "needs_human": (not approved) or urgency == "high",
        }
    }
